import {
  test,
  expect,
  setThemePlan,
  setThemeQuotaGating,
} from "../helpers/theme-browser";
import type { Locator } from "@playwright/test";

async function divider(
  locator: Locator,
  side: "top" | "bottom" | "left",
  muted = "--muted-foreground",
) {
  await expect(locator).toBeVisible();
  await expect(locator).toHaveCSS(`border-${side}-width`, "1px");
  await expect(locator).toHaveCSS(`border-${side}-style`, "dotted");
  await expect
    .poll(() =>
      locator.evaluate(
        (element, { muted, side }) => {
          const probe = document.createElement("span");
          probe.style.color = `color-mix(in srgb, var(${muted}) 85%, transparent)`;
          element.append(probe);
          const expected = getComputedStyle(probe).color;
          const actual = getComputedStyle(element).getPropertyValue(
            `border-${side}-color`,
          );
          probe.remove();
          return actual === expected;
        },
        { muted, side },
      ),
    )
    .toBe(true);
}

for (const [name, appearance, mode] of [
  ["Lavender", "purple", "light"],
  ["Nightbloom", "purple", "dark"],
  ["Chalk", "vercel", "light"],
  ["Obsidian", "vercel", "dark"],
]) {
  test(`separators: ${name} boundaries preserve controls and card outlines`, async ({
    page,
    themeUser,
  }, info) => {
    await page.setViewportSize({ width: 1440, height: 1000 });
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.addInitScript(
      ({ appearance, mode }) => {
        localStorage.setItem("mailloop-appearance", appearance);
        localStorage.setItem("mailloop-theme", mode);
      },
      { appearance, mode },
    );
    await page.goto("/settings");
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      appearance,
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
    const nav = page.getByRole("navigation", { name: "Settings sections" });
    await divider(nav, "left");
    const account = page.getByRole("button", {
      name: "Account menu",
      exact: true,
    });
    await expect(account).toHaveCSS("border-top-style", "solid");
    await account.click();
    await divider(page.locator(".workspace-account-heading"), "bottom");
    await expect(
      page.getByRole("menu", { name: "Account", exact: true }),
    ).toHaveCSS("border-top-style", "solid");
    await page.keyboard.press("Escape");
    await page
      .getByRole("button", { name: "Help with settings", exact: true })
      .click();
    await divider(page.locator(".tutorial-footer"), "top");
    await expect(page.locator(".tutorial-card")).toHaveCSS(
      "border-top-style",
      "solid",
    );
    await page
      .getByRole("button", { name: "Close tutorial", exact: true })
      .click();
    await page.setViewportSize({ width: 859, height: 1000 });
    await expect(nav).toHaveCSS("border-left-width", "0px");
    await page.setViewportSize({ width: 1440, height: 1000 });
    await setThemeQuotaGating(true);
    await setThemePlan(themeUser, "FREE");
    await page.goto("/usage");
    const comparison = page.locator("[data-plan-comparison]");
    await divider(comparison, "left");
    await expect(comparison).toHaveCSS("border-top-width", "0px");
    await expect(page.locator("[data-usage-plan-card]")).toHaveCSS(
      "border-top-style",
      "solid",
    );
    await page.setViewportSize({ width: 390, height: 1000 });
    await divider(comparison, "top");
    await expect(comparison).toHaveCSS("border-left-width", "0px");
    await info.attach(`${name}-usage-separators`, {
      body: await comparison.screenshot({
        path: info.outputPath(`${name}-usage-separators.png`),
      }),
      contentType: "image/png",
    });
    await page.goto("/pricing");
    await divider(
      page.locator(".pricing-header-wrap"),
      "bottom",
      "--pricing-muted",
    );
    await divider(page.locator("th").first(), "bottom", "--pricing-muted");
    await divider(page.locator("footer"), "top", "--pricing-muted");
    await expect(page.locator(".upgrade-card").first()).toHaveCSS(
      "border-top-style",
      "solid",
    );
    await page.context().clearCookies();
    await page.setViewportSize({ width: 1440, height: 1000 });
    await page.goto("/");
    await expect(page.locator(".landing-navbar-pill")).toHaveCSS(
      "border-bottom-style",
      "solid",
    );
    await divider(
      page.locator(".landing-activity li").first(),
      "bottom",
      "--landing-muted",
    );
  });
}
